@spec editor_verbs_spec  src=tests/specs/editor_verbs_spec.lua  loc=231  sha=3a958aa  cases=10
@exercises swingEditor (se), configManager (h.cm), temperEditor (te)
@surface   se:open, se:libraryDescriptor, cm:getAt, te:libraryDescriptor
@harness   mk

# Intent
  Verb descriptors on the swing/temper editors under the library model:
  `publish` lifts a project copy into the shared library, `revert` discards
  project drift back to its source, and `tidy` (swing only) drops pristine
  unreferenced project copies. Instantiated over a harness cm/ds with a lib
  service; imgui stubbed via package.preload. Recipe lifted from
  temperEditor_tree_spec.

# Helpers
  @fn mkLib(h)  @ 19-24
  @fn facadeStub()  @ 28-37
      -- Swing reaches the arrange/tracker services only for the reference scan and
      -- default-slot resolution; a leaf on each covers the descriptor path.
  @fn mkModalHost(captured)  @ 41-46
      -- modalHost stub: no-op registerKind, plus capture the last openConfirm args so
      -- the confirm-gated publish path is observable.
  @fn mkSwing(h)  @ 48-59
  @fn mkTemper(h, inUse)  @ 61-73

# Cases
  @case 'swing onPublish lifts a project copy into the library tier'  [harness]  @ 77-89
  @case 'swing onPublish confirms before overwriting a divergent library copy'  [harness]  @ 92-108
  @case 'temper onPublish lifts a fresh project copy without confirming'  [harness]  @ 111-123
  @case 'temper onPublish confirms before overwriting a divergent library copy'  [harness]  @ 126-142
  @case 'swing onRevert restores a divergent project copy from its source'  [harness]  @ 145-158
  @case 'swing descriptor flags a divergent project row as modified'  [harness]  @ 161-172
  @case 'temper descriptor flags a divergent project row as modified'  [harness]  @ 175-186
  @case 'swing and temper descriptors both expose onTidy'  [harness]  @ 189-197
  @case 'swing onTidy drops a pristine unreferenced copy, keeps a divergent one'  [harness]  @ 200-213
  @case 'temper onTidy drops a pristine unreferenced copy, keeps a divergent one'  [harness]  @ 216-229

